uint32_t get_100_bits_from_table(uint16_t *intable, struct UNSP *read_struct) { /* <=== get_100_bits_from_table */ 
  uint32_t count = 1;

  while (count<0x100)
    count = (count*2)|getbit_from_table(&intable[count], read_struct);
  return count&0xff;
}

uint32_t get_n_bits_from_table(uint16_t *intable, uint32_t bits, struct UNSP *read_struct) { /* <=== get_n_bits_from_table */ 
  uint32_t count = 1;
  uint32_t bitcounter;

  /*  if (bits) { always set! */
  bitcounter = bits;
  while (bitcounter--)
    count = count*2 + getbit_from_table(&intable[count], read_struct);
  /*  } */

  return count-(1<<(bits&0xff));
}

